        // Load tiles into shared memory
        int tile_row = k * TILE_SIZE + threadIdx.x;
        int tile_col = k * TILE_SIZE + threadIdx.y;

        if (row < N && tile_row < N) {
            tile_A[threadIdx.y][threadIdx.x] = A[row * N + tile_row];
