#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define REG_TILE_SIZE 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_SIZE][TILE_SIZE];
    __shared__ float tile_B[TILE_SIZE][TILE_SIZE];

    int block_row = blockIdx.y * TILE_SIZE;
    int block_col = blockIdx.x * TILE_SIZE;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Register tiling for each thread
    float reg_C[REG_TILE_SIZE][REG_TILE_SIZE] = {0};

    for (int k = 0; k < N; k += TILE_SIZE) {
        // Collaborative loading of tiles
        for (int load_row = 0; load_row < REG_TILE_SIZE; load_row++) {
            for (int load_col = 0; load_col < REG_TILE_SIZE; load_col++) {
                int global_row = block_row + thread_row * REG_TILE_SIZE + load_row;
                int global_col = k + thread_col * REG_TILE_SIZE + load_col;

                if (global_row < N && global_col < N) {
                    tile_A[thread_row * REG_TILE_SIZE + load_row][thread_col * REG_TILE_SIZE + load_col] = 
                        A[global_row * N + global_col];
                } else {
                    tile_A[thread_row * REG_TILE_SIZE + load_row][thread_col * REG_TILE_SIZE + load_col] = 0.0f;
                }

                global_row = k + thread_row * REG_TILE_SIZE + load_row;
                global_col = block_col + thread_col * REG_TILE_SIZE + load_col;

                if (global_row < N && global_col < N) {
                    tile_B[thread_row * REG_TILE_SIZE + load_row][thread_col * REG_TILE_SIZE + load_col] = 
                        B[global_row * N + global_col];
                } else {
                    tile_B[thread_row * REG_TILE_SIZE + load_row][thread_col * REG_TILE_SIZE + load_col] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute using register tiling
        for (int inner_k = 0; inner_k < TILE_SIZE; inner_k++) {
            float reg_A[REG_TILE_SIZE];
            float reg_B[REG_TILE_SIZE];

            // Load into registers
            #pragma unroll
            for (int i = 0; i < REG_TILE_SIZE; i++) {
                reg_A[i] = tile_A[thread_row * REG_TILE_SIZE + i][inner_k];
                reg_B[i] = tile_B[inner_k][thread_col * REG_TILE_SIZE + i];
