            for (int i = 0; i < REG_TILE_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < REG_TILE_SIZE; j++) {
                    reg_C[i][j] += reg_A[i] * reg_B[j];
                }
            }
        }

        __syncthreads();
    }

    // Write results back to global memory
    for (int i = 0; i < REG_TILE_SIZE; i++) {
        for (int j = 0; j < REG_TILE_SIZE; j++) {
            int global_row = block_row + thread_row * REG_TILE_SIZE + i;
