    float reg_C[THREAD_TILE_M][THREAD_TILE_N];

    // Initialize register array
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; i++) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_N; j++) {
            reg_C[i][j] = 0.0f;
        }
